// Wider searches of the HNSW indexes (how many neighbours each looks at).
func (q *Queries) SearchWidely(ctx context.Context, ef string) error {
	_, err := q.db.Exec(ctx, searchWidely, ef)
	return err
}

const setSweepModel = `-- name: SetSweepModel :one
WITH before AS (SELECT model FROM meaning_sweep)
UPDATE meaning_sweep SET model = $1, unavailable_until = NULL
WHERE meaning_sweep.model IS DISTINCT FROM $1 OR unavailable_until IS NOT NULL
RETURNING ((SELECT before.model FROM before) IS DISTINCT FROM $1)::boolean AS changed
`

// The model (and reading rules) that read the latest; changed: everyone is read again.
func (q *Queries) SetSweepModel(ctx context.Context, model *string) (bool, error) {
	row := q.db.QueryRow(ctx, setSweepModel, model)
	var changed bool
	err := row.Scan(&changed)
	return changed, err
}

const setUnavailable = `-- name: SetUnavailable :exec
UPDATE meaning_sweep SET unavailable_until = $1
`

func (q *Queries) SetUnavailable(ctx context.Context, until *time.Time) error {
	_, err := q.db.Exec(ctx, setUnavailable, until)
	return err
}

const sweepRan = `-- name: SweepRan :exec
UPDATE meaning_sweep SET cursor_id = $1, passes = passes + $2::int, due_at = $3, ran_at = now()
WHERE chain = $4
`

type SweepRanParams struct {
	CursorID string
	Finished int32
	DueAt    time.Time
	Chain    int32
}

func (q *Queries) SweepRan(ctx context.Context, arg SweepRanParams) error {
	_, err := q.db.Exec(ctx, sweepRan,
		arg.CursorID,
		arg.Finished,
		arg.DueAt,
		arg.Chain,
	)
	return err
}

const touchQuery = `-- name: TouchQuery :exec
UPDATE meaning_query SET used_at = now() WHERE id = $1 AND used_at < now() - interval '1 hour'
`

func (q *Queries) TouchQuery(ctx context.Context, id string) error {
	_, err := q.db.Exec(ctx, touchQuery, id)
	return err
}
